        p=np.c_[p,q]; w=p[:n]; results.append(p[n:]@solve(w.T@w+.001*np.eye(w.shape[1]),w.T@y,assume_a='pos'))
    return np.mean(results,axis=0)

def solve_batch(study: dict) -> dict:
